data: {"id":"202609190929232cbebdee04e44f49","created":1789781363,"object":"chat.completion.chunk","model":"glm-5.3-flash","choices":[{"index":0,"delta":{"tool_calls":[{"id":"call_13dcadc95fe54ae19489c702","index":0,"type":"function","function":{"name":"apply_edits","arguments":"{\"edits\":[{\"new_text\": \"MEM_STATIC void ZSTD_window_clear(ZSTD_window_t* window)\\n{\\n    size_t const endT = (size_t)(window->nextSrc - window->base);\\n    U32 const end = (U32)endT;\\n\\n    window->lowLimit = end;\\n    window->dictLimit = end;\\n}\\n\\n/**\\n * ZSTD_window_init():\\n * Initialize a window to the state it should be in when it is first created.\\n * The first reference position starts at 1 (and not 0), so that the first\\n * input position is always a valid position for a match, even during the\\n * first usage of the context (see issue #1241).\\n */\\nMEM_STATIC void ZSTD_window_init(ZSTD_window_t* window)\\n{\\n    memset(window, 0, sizeof(*window));\\n    window->base = (BYTE const*)\\\"\\\";\\n    window->dictBase = (BYTE const*)\\\"\\\";\\n    window->dictLimit = 1;    /* start from 1, so that 1st position is valid */\\n    window->lowLimit = 1;     /* it ensures first and later CCtx usages compare from a non-null prefix */\\n    window->nextSrc = window->base + 1;   /* see issue #1241 */\\n}\", \"old_text\": \"MEM_STATIC void ZSTD_window_clear(ZSTD_window_t* window)\\n{\\n    size_t const endT = (size_t)(window->nextSrc - window->base);\\n    U32 const end = (U32)endT;\\n\\n    window->lowLimit = end;\\n    window->dictLimit = end;\\n}\", \"path\": \"lib/compress/zstd_compress_internal.h\", \"source_sha256\": \"024a72b519397e9670eb34a1fcc75089011ca4a4fceb4e9a4ad0aca370734dd9\"}, {\"new_text\": \"    ms->hashLog3 = hashLog3;\\n    ZSTD_window_init(&ms->window);\\n    ZSTD_invalidateMatchState(ms);\", \"old_text\": \"    ms->hashLog3 = hashLog3;\\n    memset(&ms->window, 0, sizeof(ms->window));\\n    ZSTD_invalidateMatchState(ms);\", \"path\": \"lib/compress/zst